def encode_backlen(n):
    out = bytearray()
    out.append(n & 0x7f)
    n >>= 7
    while n > 0:
        out.append((n & 0x7f) | 0x80)
        n >>= 7
    return bytes(out)

def decode_backlen(buf, end):
    n = 0; shift = 0; i = end - 1
    while True:
        b = buf[i]
        n |= (b & 0x7f) << shift
        shift += 7
        i -= 1
        if not (b & 0x80):
            break
    return n, i + 1

for n in [1, 127, 128, 16383, 16384]:
    enc = encode_backlen(n)
    dec, start = decode_backlen(enc, len(enc))
